#!/usr/bin/env python3
"""Fill upgrade_m.jsonl to 200+ pairs"""
import json, pathlib

OUT = pathlib.Path('/workspace/data_upgrades')

extra = [
    ("What is EXPLAIN BUFFERS in PostgreSQL?", "EXPLAIN (ANALYZE, BUFFERS) adds buffer hit/miss statistics to the plan. shared_blks_hit shows pages served from buffer cache; shared_blks_read shows physical disk reads. A high ratio of reads to hits on a key table indicates the working set exceeds shared_buffers and benefits from increasing cache size or adding an index. EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) produces machine-readable output for programmatic analysis and plan comparison tools."),
    ("What is tablespace in PostgreSQL?", "A tablespace defines a location on disk where database objects are stored. The default tablespace (pg_default) uses the data directory. CREATE TABLESPACE fast LOCATION '/mnt/nvme/pg'; allows placing hot tables or indexes on faster storage. Indexes can be placed on a different tablespace than their table. Tablespaces enable storage tiering: hot data on NVMe SSDs, warm data on SATA SSDs, cold data on HDD, without migrating the entire cluster."),
    ("What is logical decoding in PostgreSQL?", "Logical decoding decodes the WAL into a stream of row-level changes (INSERT/UPDATE/DELETE) in a human-readable or structured format, without requiring knowledge of the internal storage format. It uses output plugins (pgoutput is the built-in plugin used by logical replication; wal2json produces JSON; decoderbufs produces Protobuf for Debezium). Logical decoding underpins logical replication, CDC, and event sourcing architectures."),
    ("What is unlogged table in PostgreSQL?", "UNLOGGED tables skip WAL logging entirely, making writes 5-10x faster than regular tables. Trade-off: unlogged tables are truncated on crash recovery (data is lost) and cannot be replicated. Suitable for: temporary staging tables in ETL pipelines, session state, and derived data that can be regenerated. CREATE UNLOGGED TABLE avoids the WAL overhead when durability is not required and the data can be reconstructed."),
    ("What is the difference between heap and index in PostgreSQL?", "The heap is the main table storage file containing all rows in insertion order (pages of 8KB). An index is a separate data structure (B-tree, GIN, etc.) containing keys and row pointers (TIDs -- tuple identifiers: page number + offset). Index scans fetch the TID from the index then retrieve the full row from the heap (random I/O). Index-only scans use a covering index plus the visibility map to answer queries without touching the heap. Sequential heap scans are sequential I/O, often faster for large result sets."),
    ("What is toast in PostgreSQL?", "TOAST (The Oversized-Attribute Storage Technique) handles column values larger than ~2KB. PostgreSQL stores large values in a separate TOAST table, compressing them with pglz (or lz4 in PG14+) and chunking them into 2KB pieces. The main table row stores a pointer to the TOAST entry. Operations on non-TOAST columns do not fetch TOAST data. TOAST is transparent to queries but can cause performance issues when queries unnecessarily select large TOAST columns -- use column-level SELECT to avoid fetching unneeded large values."),
    ("What is synchronous_commit in PostgreSQL?", "synchronous_commit controls whether a COMMIT waits for WAL to be flushed to disk (and optionally to replicas) before returning to the client. Values: on (default -- fsync WAL, full durability); off (return immediately after WAL is queued -- up to 3x faster writes, risk of losing last ~200ms of commits on crash); local (fsync locally but not to replicas); remote_write (replica has received WAL to OS buffer); remote_apply (replica has applied WAL). Per-transaction override: SET LOCAL synchronous_commit = off."),
    ("What is lock contention in databases?", "Lock contention occurs when multiple transactions compete for the same lock. In PostgreSQL, row-level locks (FOR UPDATE, FOR SHARE), table locks (ACCESS EXCLUSIVE for ALTER TABLE), and advisory locks are sources of contention. pg_locks joined with pg_stat_activity reveals blocking queries. Long-running transactions holding row locks block other writers. Solutions: shorten transactions, use SELECT FOR UPDATE SKIP LOCKED (job queues), partition hotspot tables, and use application-level queuing to serialise access to contested resources."),
    ("What is an index scan vs bitmap scan in PostgreSQL?", "Index Scan: fetches one row at a time from the heap following each TID from the index -- random I/O, efficient for small result sets. Bitmap Index Scan: builds a bitmap of heap page numbers matching the index condition, then performs a Bitmap Heap Scan fetching all matching pages in physical order -- sequential-ish I/O, efficient for medium result sets (hundreds to thousands of rows). Multiple bitmap indexes can be ANDed or ORed before the heap scan. Sequential Scan: reads the entire heap in order -- best for large result fractions (>10-20%)."),
    ("What is hot update in PostgreSQL?", "HOT (Heap Only Tuple) updates avoid creating a new index entry when a row is updated and no indexed column changes. Instead, the old tuple is marked dead and the new tuple is linked via a HOT chain on the same heap page. The index still points to the old tuple, which chains to the new one. HOT updates significantly reduce index bloat and VACUUM work for frequently updated rows with non-indexed columns (e.g., status flags, counters). Set fillfactor < 100 on hot tables to leave room for HOT updates on the same page."),
    ("What is fillfactor in PostgreSQL?", "Fillfactor is the percentage of each page filled during initial data load and INSERTs (default 100). Setting fillfactor=70 on a table leaves 30% of each page free for HOT updates -- updates to non-indexed columns can stay on the same page, enabling HOT chains and reducing index bloat. For read-heavy tables: fillfactor=100 maximises density. For write-heavy tables with frequent updates: fillfactor=70-80 reduces index maintenance overhead and improves HOT update rates."),
    ("What is a database hot path?", "A hot path is a code or query path executed very frequently -- the critical path for performance. In database design: identify the top 5 queries by total execution time (pg_stat_statements); ensure each has the optimal index; consider materialised views or caching for repeated expensive aggregations; avoid N+1 queries on hot paths; and use connection pooling to minimise connection overhead. Measure with EXPLAIN ANALYZE after each change to confirm improvement."),
    ("What is the difference between UNION and UNION ALL?", "UNION combines results of two queries and removes duplicates (requires sorting or hashing -- expensive for large sets). UNION ALL combines results without deduplication -- faster because it avoids the sort/hash step. Use UNION ALL when you know results are already distinct or duplicates are acceptable. INTERSECT returns rows in both result sets; EXCEPT returns rows in the first but not second. All set operators require compatible column types and counts in both SELECT lists."),
    ("What is a materialized CTE in PostgreSQL?", "In PostgreSQL, WITH (MATERIALIZED) forces the CTE to be evaluated once and its result stored as a temporary table. NOT MATERIALIZED allows the planner to inline the CTE and optimise it with the outer query. Prior to PG12, all CTEs were automatically materialised (acting as an optimisation fence). PG12+ uses NOT MATERIALIZED by default when safe, enabling better plan optimisation. Use MATERIALIZED explicitly when the CTE has side effects or when you want to prevent it from being evaluated multiple times."),
    ("What is a foreign key constraint vs application-level enforcement?", "Database-enforced foreign keys guarantee referential integrity unconditionally -- no application bug can insert an orphaned row. They are checked on every INSERT/UPDATE/DELETE, add a slight overhead (index lookup on the referenced table), and require the referenced row to exist at commit time. Application-level enforcement is more flexible (can be batched, async) but depends on all code paths being correct -- bugs lead to orphaned rows. Database constraints are the reliable baseline; application logic handles business rules beyond pure referential integrity."),
    ("What is a partial unique index?", "A partial unique index enforces uniqueness only over rows satisfying a WHERE condition. Example: CREATE UNIQUE INDEX ON users(email) WHERE deleted_at IS NULL -- enforces email uniqueness only among non-deleted users, allowing multiple deleted users with the same email. Useful for: soft-delete tables, draft vs published states, and conditional uniqueness constraints that cannot be expressed with a plain unique constraint. Partial unique indexes are smaller and cheaper to maintain than full unique indexes."),
    ("What is pg_partman?", "pg_partman is a PostgreSQL extension that automates partition management for range and list partitioned tables. It creates new partitions ahead of time (based on a configurable premake count), drops old partitions beyond a retention period, and maintains the partition hierarchy. A background worker (or pg_cron) triggers maintenance. It eliminates manual partition creation for time-series tables -- new daily/monthly/yearly partitions are created automatically, and old ones are detached and dropped on schedule."),
    ("What is Citus?", "Citus is a PostgreSQL extension (now part of Microsoft Azure) that transforms PostgreSQL into a distributed database. It shards tables across multiple worker nodes using a distribution column. The coordinator node receives queries and distributes them to workers (push-down for co-located joins). Reference tables are replicated to all workers for efficient joins. Citus is transparent to the application (standard PostgreSQL protocol). Used by Figma, Heap, and others for multi-tenant SaaS with per-tenant sharding."),
    ("What is HypoPG?", "HypoPG is a PostgreSQL extension that allows creating hypothetical indexes -- indexes that exist only in memory and are never actually built. The planner treats them as real indexes. This lets you test whether a proposed index would be used by a query (and estimate its benefit) before spending time building it on a large production table. Workflow: SELECT * FROM hypopg_create_index('CREATE INDEX ON orders(customer_id)'); then EXPLAIN the query to see if the hypothetical index is used."),
    ("What is auto_explain in PostgreSQL?", "auto_explain is a PostgreSQL module that automatically logs execution plans for slow queries. When log_min_duration (e.g., 1000ms) is exceeded, auto_explain writes the EXPLAIN ANALYZE output to the PostgreSQL log. auto_explain.log_nested_statements logs plans for statements inside functions. auto_explain.log_buffers adds buffer statistics. It is invaluable for capturing the plans of production slow queries that are hard to reproduce interactively. Load with shared_preload_libraries = 'auto_explain'."),
    ("What is the difference between a role and a user in PostgreSQL?", "In PostgreSQL, USER and ROLE are synonyms -- CREATE USER is shorthand for CREATE ROLE WITH LOGIN. Roles can be granted to other roles (role inheritance -- the grantee inherits the permissions of the granted role). Login roles have the LOGIN attribute. Application best practice: create a read-only role (GRANT SELECT ON ALL TABLES IN SCHEMA public TO readonly_role), a read-write role, and grant these to application users. Use NOINHERIT for security-sensitive roles requiring explicit SET ROLE."),
    ("What is WAL compression in PostgreSQL?", "WAL compression (wal_compression = on in PG14+) compresses full-page images in the WAL using lz4 or zstd, reducing WAL volume by 50-80% for write-heavy workloads. Full-page images are written to WAL after each checkpoint for every page modified for the first time (to enable crash recovery without partial page writes). Compression reduces I/O for WAL archiving, streaming replication, and disk space. CPU overhead is minimal on modern hardware. WAL compression is highly recommended for write-heavy workloads."),
    ("What is pg_cron?", "pg_cron is a PostgreSQL extension that runs periodic jobs inside the database (like cron, but SQL-native). Jobs are defined as SQL statements with a cron schedule: SELECT cron.schedule('nightly-vacuum', '0 2 * * *', 'VACUUM ANALYZE orders'). Jobs run as the postgres superuser by default (configurable). pg_cron requires shared_preload_libraries = 'pg_cron'. It eliminates the need for external cron jobs for database maintenance tasks (VACUUM, ANALYZE, partition management, data archival, and aggregation refreshes)."),
    ("What is table inheritance in PostgreSQL?", "PostgreSQL supports table inheritance (CREATE TABLE child () INHERITS (parent)) where child tables contain all parent columns plus additional ones. Queries on the parent include rows from all children (unless ONLY is specified). Used to implement: simple partitioning (before declarative partitioning), polymorphic data models, and audit log structures. Limitations: foreign keys cannot reference parent tables directly; unique constraints and primary keys do not span the inheritance hierarchy. Declarative partitioning (PARTITION BY) is preferred for new designs."),
    ("What is the difference between CHAR, VARCHAR, and TEXT in PostgreSQL?", "In PostgreSQL: CHAR(n) pads values to exactly n characters (rarely useful); VARCHAR(n) stores up to n characters with no padding; TEXT stores unlimited characters. Performance: all three are stored identically internally (varlena type) -- there is no performance difference between VARCHAR(n) and TEXT. PostgreSQL's TEXT is equivalent to VARCHAR without a length limit. The length constraint on VARCHAR is only a data validation rule. Use TEXT unless you need to enforce a maximum length as a database constraint."),
    ("What is row-level locking in PostgreSQL?", "PostgreSQL provides row-level locks acquired via SELECT FOR UPDATE (exclusive), FOR NO KEY UPDATE (exclusive but allows FK-checking reads), FOR SHARE (shared), and FOR KEY SHARE (weakest -- only blocks exclusive locks). Row locks are not stored in a lock table but as flags in the row's tuple header (eliminating lock table overhead). NOWAIT returns an error immediately; SKIP LOCKED skips locked rows (job queue pattern). Row locks are released at transaction end."),
    ("What is connection authentication in PostgreSQL?", "pg_hba.conf (host-based authentication) controls which clients can connect to which databases as which roles using which authentication method. Methods: trust (no password -- for local development only); md5 (password hashed with MD5 -- deprecated, use scram-sha-256); scram-sha-256 (secure challenge-response -- recommended); peer (Unix socket -- OS user must match DB role); cert (SSL client certificate); ldap/gss/sspi (enterprise SSO). Cloud databases add IAM authentication (AWS RDS IAM auth, GCP IAM conditions)."),
    ("What is a database trigger vs constraint?", "Constraints (CHECK, UNIQUE, FK) are declarative, enforced by the DBMS engine, and apply to every statement including bulk operations. They are simpler, faster, and should be the first choice for integrity rules. Triggers are procedural code executed on specific events -- they can enforce complex multi-table rules, compute derived values, maintain audit logs, and call external systems. Triggers fire per-row or per-statement; BEFORE triggers can abort the operation; AFTER triggers see the committed state. Use constraints for data integrity; triggers for logic that cannot be expressed declaratively."),
    ("What is a generated column in PostgreSQL?", "Generated columns (PG12+) are computed automatically from other columns in the same row. STORED generated columns (CREATE TABLE t (a INT, b INT, c INT GENERATED ALWAYS AS (a + b) STORED)) persist the computed value on disk and can be indexed. VIRTUAL generated columns (not yet in PostgreSQL, available in MySQL) compute the value on read. Use cases: full-text search tsvector computed from multiple text columns; geometric expressions; and pre-computed hash columns for fast equality lookups."),
    ("What is the difference between NOW() and CURRENT_TIMESTAMP in SQL?", "In PostgreSQL, NOW() and CURRENT_TIMESTAMP are synonymous -- both return the transaction start time (the time the current transaction began, not the current wall-clock time). This means multiple calls to NOW() within a transaction return the same value. clock_timestamp() returns the actual wall-clock time, advancing within a transaction. statement_timestamp() returns the time the current statement began. For audit timestamps, CURRENT_TIMESTAMP (transaction time) is appropriate; for elapsed time measurement, clock_timestamp() is needed."),
    ("What is a leaky bucket rate limiter using PostgreSQL?", "A token bucket rate limiter can be implemented in PostgreSQL using an advisory lock + a tokens table: UPDATE rate_limit SET tokens = LEAST(capacity, tokens + rate * EXTRACT(EPOCH FROM now()-last_refill)), last_refill = now() WHERE user_id = X; then check if tokens >= 1 and decrement. Advisory locks prevent concurrent updates from the same user causing race conditions. This avoids a separate Redis dependency for rate limiting in low-to-moderate traffic APIs backed by PostgreSQL."),
]

existing = sum(1 for _ in OUT.open()) if OUT.exists() else 0
print(f"Existing: {existing}")

with OUT.open("a") as f:
    for q, a in extra:
        f.write(json.dumps({"messages": [
            {"role": "user", "content": q},
            {"role": "assistant", "content": a}
        ]}) + "\n")

total = sum(1 for _ in OUT.open())
print(f"Total: {total}")
assert total >= 200
print("PASS")
